style.css:
@-moz-document domain("youtube.com") {
/* Hide the default YouTube spinner */
  ytd-player yt-page-navigation-progress,
  .ytp-spinner,
  #spinner,
  .ytp-spinner-container,
  .ytp-spinner-svg {
    display: none !important;
  }

  /* Create a custom spinning cat overlay */
  body::before {
    content: "";
    position: fixed;
    top: 50%;
    left: 50%;
    width: 100px;
    height: 100px;
    margin-top: -50px;
    margin-left: -50px;
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/0/0a/Cat_March_2010-1a.jpg");
    background-size: cover;
    background-position: center;
    border-radius: 50%;
    z-index: 99999;
    animation: maxwell-spin 2s linear infinite;
    pointer-events: none;
  }

  @keyframes maxwell-spin {
    from {
      transform: rotate(0deg);
    }
    to {
      transform: rotate(360deg);
    }
  }
}
